Algorithm COOP_LAGRANGIAN_PATCH_LEARN(problem_spec, time_limit, params, seed)
  Init hooks := ENCODE, DECODE, COST, CONSTRAINTS, RELAX_SOLVER, REPAIR, OPERATORS, BUILD_MODEL, SURROGATE, CLUSTER, PATCHER, PARTIAL_OPT
  population := SeedPopulation(problem_spec, seed, heuristics+relaxed_solutions); archive := {}; multipliers := zero(CONSTRAINTS); model := BUILD_MODEL(population, archive)
  operator_weights := uniform(OPERATORS); hierarchy := build_multilevel_coarsening(problem_spec, params.levels)
  while not STOP(time_limit, iteration, stagnation):
    // 1. Global guidance: solve relaxed master under multipliers at current hierarchy level
    x_relaxed := RELAX_SOLVER(problem_spec, multipliers, hierarchy.current_level, params)
    // 2. Cooperative decomposition: derive focused subproblems from model, population and relaxed solution
    subproblems := DECOMPOSE(population, model, x_relaxed, params)
    budget := AllocateBudgetAdaptive(subproblems, model, archive, params)
    for sub in Prioritize(subproblems, budget):
      parent := SelectParent(population, archive, sub, fitness+diversity+multiplier_signal)
      op := ContextualChoose(operator_weights, op_context=sub, model)
      child := APPLY_OPERATOR_RESTRICTED(parent, op, sub); child := REPAIR(child)
      child := PARTIAL_OPT(child, sub, problem_spec, params); child.cost := SURROGATE(child, model)
      archive, population := CooperativeIngest(population, archive, child, replace_policy)
      credits[op] += CreditFunction(parent, child, feasibility_gain, novelty, multiplier_relief)
    // 3. Hierarchical patch-and-learn: cluster fractional/infeasible regions, patch into feasible candidates and refine
    clusters := CLUSTER(x_relaxed, problem_spec, multipliers); candidate := PATCHER(x_relaxed, clusters, PARTIAL_OPT, params); candidate := REPAIR(candidate)
    if COST(candidate) < best_cost and VALIDATE(candidate, CONSTRAINTS): archive.update(candidate); best_cost := COST(candidate)
    // 4. Lagrangian update and targeted intensification
    subgrad := compute_violations(candidate, CONSTRAINTS); multipliers := UpdateMultipliers(multipliers, subgrad, params)
    hotspots := select_hotspots(subgrad, clusters, params.hotspot_threshold); for h in hotspots: candidate := PARTIAL_OPT(candidate, h, problem_spec, params); archive.update_if_better(candidate)
    // 5. Adaptation: update model, operator_weights, hierarchy and diversification
    model := PeriodicUpdate(model, population, archive, params); operator_weights := AdaptWeights(operator_weights, credits, params)
    if stagnation_detected(): hierarchy := descend_or_recoarsen(hierarchy); population := InjectDiversification(population, RELAX_SOLVER, seed)
  return DECODE(BestFromArchive(archive))

